const fs=require('fs'),assert=require('assert'),crypto=require('crypto'),vm=require('vm'),png=require('./scripts/png.cjs');global.window=global;vm.runInThisContext(fs.readFileSync('js/core.js','utf8'));const dir='备份/20261102-idle-side-whole-sync/',raw=fs.readFileSync(dir+'before.json'),p=JSON.parse(raw),original=structuredClone(p);const dec=c=>png.decode(Buffer.from(c.dataURL.split(',')[1],'base64'));const changes=[];for(const li of [11,191]){const l=p.layers[li];assert(l.visible&&l.sheetIndex===8);const source=l.frameData['8_0_2'],src=dec(source);for(const fi of [0,1,3]){const c=l.frameData['8_0_'+fi],im=dec(c),out=new Uint8Array(im.data.length),dy=fi<2?-2:0,px=c.placement?.x||0,py=c.placement?.y||0;assert(!c.placement||(c.placement.w===im.width&&c.placement.h===im.height));for(let y=0;y<src.height;y++)for(let x=0;x<src.width;x++){const si=(y*src.width+x)*4;if(!src.data[si+3])continue;const tx=x-px,ty=y+dy-py;assert(tx>=0&&ty>=0&&tx<im.width&&ty<im.height,'copy would crop');out.set(src.data.subarray(si,si+4),(ty*im.width+tx)*4);}let n=0;for(let i=0;i<out.length;i+=4)if([0,1,2,3].some(k=>im.data[i+k]!==out[i+k]))n++;c.dataURL='data:image/png;base64,'+png.encode(im.width,im.height,out).toString('base64');changes.push({layer:li,frame:fi+1,changedPixels:n,headOffsetY:dy});}}
const restored=structuredClone(p);for(const li of [11,191])for(const fi of [0,1,3])restored.layers[li].frameData['8_0_'+fi]=original.layers[li].frameData['8_0_'+fi];assert.deepEqual(restored,original);fs.writeFileSync(dir+'candidate.json',JSON.stringify(p));fs.writeFileSync(dir+'diff.json',JSON.stringify(changes,null,2));fs.writeFileSync(dir+'sha256.txt',crypto.createHash('sha256').update(raw).digest('hex'));
for(const bg of [[221,213,237,255],[35,35,45,255]]){const W=31,H=36,S=8,out=new Uint8Array(W*4*S*H*S*4);for(let fi=0;fi<4;fi++){const data=new Uint8Array(W*H*4);for(const l of PE.getRenderLayers(p,8,0)){if(!PE.isLayerVisible(p,l,8))continue;const c=l.frameData?.['8_0_'+fi];if(!c)continue;const im=dec(c);for(let y=0;y<im.height;y++)for(let x=0;x<im.width;x++){const tx=x+(c.placement?.x||0),ty=y+(c.placement?.y||0),i=(y*im.width+x)*4;if(tx>=0&&ty>=0&&tx<W&&ty<H&&im.data[i+3])data.set(im.data.subarray(i,i+4),(ty*W+tx)*4);}}assert(data.some((v,i)=>i%4===3&&v));for(let y=0;y<H*S;y++)for(let x=0;x<W*S;x++){const j=(Math.floor(y/S)*W+Math.floor(x/S))*4;out.set(data[j+3]?data.subarray(j,j+4):bg,(y*W*4*S+fi*W*S+x)*4);}}fs.writeFileSync(dir+'preview-'+bg[0]+'.png',png.encode(W*4*S,H*S,out));}console.log(JSON.stringify(changes));console.log('PASS unchanged fields and restoration');
